#!/usr/bin/env python3
"""Refuse any workflow step that runs an action from a moving reference.

Every `uses:` in the workflows must name a full 40-character commit SHA
(`owner/repo[/path]@<sha>`), a local action (`./path`), or a Docker image by
digest (`docker://image@sha256:<64 hex>`). A tag or branch can be moved by
whoever controls the action's repository, and these workflows run with this
repository's tokens.

The workflows were generated by Upptime, whose template update rewrote them
with tags and branches. That update is removed, so an Upptime upgrade is done
by hand: regenerate, re-pin, run this check.

Usage: check-pinned-actions.py [workflow directory]  (default .github/workflows)
Exits 0 when every reference is pinned; otherwise prints one line per
offending reference and exits 1.
"""
import pathlib
import re
import sys

USES = re.compile(r"""^\s*(?:-\s+)?uses:\s*["']?([^"'\s#]+)""")
MENTIONS_USES = re.compile(r"""(?:^|[\s{,-])uses\s*:""")
PINNED = re.compile(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+(?:/[^@\s]+)?@[0-9a-f]{40}$")
DOCKER_BY_DIGEST = re.compile(r"^docker://[^@\s]+@sha256:[0-9a-f]{64}$")


def offending_references(path):
    """(line number, text) for each reference in one workflow that is not pinned."""
    found = []
    references = 0
    for number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        if line.lstrip().startswith("#"):
            continue
        match = USES.match(line)
        if match is None:
            # A `uses:` this reader cannot follow (value on the next line, flow
            # style) is refused rather than skipped.
            if MENTIONS_USES.search(line):
                references += 1
                found.append((number, line.strip() + " (cannot read the reference)"))
            continue
        references += 1
        reference = match.group(1)
        if reference.startswith("./") or PINNED.match(reference) or DOCKER_BY_DIGEST.match(reference):
            continue
        found.append((number, reference + " is not pinned to a full commit SHA"))
    return references, found


def main(argv):
    root = pathlib.Path(argv[1] if len(argv) > 1 else ".github/workflows")
    workflows = sorted(p for p in root.iterdir() if p.suffix in (".yml", ".yaml"))
    if not workflows:
        print(f"no workflow files under {root}")
        return 1
    total = 0
    unpinned = 0
    for path in workflows:
        references, found = offending_references(path)
        total += references
        unpinned += len(found)
        for number, text in found:
            print(f"{path}:{number}: {text}")
    print(f"{total} action references in {len(workflows)} workflows, {unpinned} not pinned")
    return 1 if unpinned else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
